package net.atlasauth.pca;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;

/**
 * 0.5 mutation kills for {@link IntentHistory}: a differential test against the TS reference (the shared k05 oracle,
 * test-data/k05-intenthistory.json.gz, generated by tools/pca-audit/k05-oracles/intenthistory-oracle.mts). Every result compares
 * by JSON value. Where the reference throws, accPreState / accPost return null and the other functions throw; where the
 * reference's inWindow falls off its switch (undefined, falsy) the Java answer is false.
 */
public class K05IntentHistoryDiffTest {
    static final String MODULE = "k05-intenthistory";
    static final int MUST_THROW = 0, THROW_IS_NULL = 1, UNDEFINED_IS_FALSE = 2;

    @SuppressWarnings("unchecked") static Map<String, Object> m(Object o) { return (Map<String, Object>) o; }
    @SuppressWarnings("unchecked") static List<Object> l(Object o) { return (List<Object>) o; }
    static Map<String, Object> mapOrNull(Object o) { return o instanceof Map ? m(o) : null; }

    interface Fn { Object apply(List<?> a) throws Exception; }

    static void each(String fn, int mode, Fn f) throws Exception {
        List<Map<String, Object>> cases = K05Oracle.of(MODULE, fn);
        assertFalse(cases.isEmpty(), "no oracle cases for " + fn);
        List<String> bad = new ArrayList<>();
        for (Map<String, Object> c : cases) {
            Object want = c.get("out");
            boolean throwsWant = want instanceof Map && m(want).containsKey("$throws");
            if (throwsWant && mode == THROW_IS_NULL) { want = null; throwsWant = false; }
            if (want == null && mode == UNDEFINED_IS_FALSE) want = false;
            Object got = null;
            Throwable err = null;
            try { got = f.apply((List<?>) c.get("args")); } catch (Throwable t) { err = t; }
            if (throwsWant) {
                if (err == null) bad.add(c.get("name") + "\n  want: throw " + c.get("out") + "\n  got:  " + got);
            } else if (err != null) {
                bad.add(c.get("name") + "\n  want: " + want + "\n  got:  THROWS " + err);
            } else if (!IntentJs.jsonEquals(want, got)) {
                bad.add(c.get("name") + "\n  want: " + want + "\n  got:  " + got);
            }
        }
        assertTrue(bad.isEmpty(), bad.size() + " of " + cases.size() + " divergent case(s):\n" + String.join("\n", bad.subList(0, Math.min(bad.size(), 40))));
    }

    @Test void inWindow() throws Exception {
        each("inWindow", UNDEFINED_IS_FALSE, a -> IntentHistory.inWindow(mapOrNull(a.get(0)), a.get(1), a.get(2)));
    }

    @Test void accKeyOf() throws Exception {
        each("accKeyOf", MUST_THROW, a -> IntentHistory.accKeyOf(m(a.get(0)), mapOrNull(a.get(1))));
    }

    @Test void accPreState() throws Exception {
        each("accPreState", THROW_IS_NULL, a -> {
            Map<String, Object> cand = m(a.get(2));
            return IntentHistory.accPreState(m(a.get(0)), l(a.get(1)), m(cand.get("params")), cand.get("t"), a.get(3));
        });
    }

    @Test void accPost() throws Exception {
        each("accPost", THROW_IS_NULL, a -> {
            Map<String, Object> cand = m(a.get(2));
            return IntentHistory.accPost(m(a.get(0)), l(a.get(1)), (String) cand.get("verb"), m(cand.get("params")), cand.get("t"), a.get(3));
        });
    }

    @Test void monitorStep() throws Exception {
        each("monitorStep", MUST_THROW, a -> IntentHistory.monitorStep(m(a.get(0)), (String) a.get(1), mapOrNull(a.get(2))));
    }

    @Test void monitorState() throws Exception {
        each("monitorState", MUST_THROW, a -> IntentHistory.monitorState(m(a.get(0)), l(a.get(1))));
    }

    /** The renderings the counter cannot reach from a JSON declaration (a negative infinity, a negative exponent form). */
    @Test void jsStringRendersLikeJavaScript() {
        assertEquals("NaN", IntentHistory.jsString(Double.NaN));
        assertEquals("Infinity", IntentHistory.jsString(Double.POSITIVE_INFINITY));
        assertEquals("-Infinity", IntentHistory.jsString(Double.NEGATIVE_INFINITY));
        assertEquals("0", IntentHistory.jsString(-0.0));
        assertEquals("-1.5e+21", IntentHistory.jsString(-1.5e21));
        assertEquals("-1e-7", IntentHistory.jsString(-1e-7));
        assertEquals("-0.000001", IntentHistory.jsString(-1e-6));
        assertEquals("-12.5", IntentHistory.jsString(-12.5));
    }
}
